  KEY `ix_exam_results_status` (`status`),
  CONSTRAINT `exam_results_ibfk_1` FOREIGN KEY (`exam_id`) REFERENCES `exams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_results_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_results_ibfk_3` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_results_ibfk_4` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_results_ibfk_5` FOREIGN KEY (`submission_id`) REFERENCES `result_submissions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exam_results_ibfk_6` FOREIGN KEY (`release_batch_id`) REFERENCES `result_release_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exam_results_ibfk_7` FOREIGN KEY (`recorded_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
