INSERT INTO `notification_templates` VALUES (13,'ATTENDANCE_ABSENT','Student Absence Alert (Somali)','Ogeysiis Maqnaansho - {{student_name}}','Asc {{guardian_name}}, waxaan ku ogeysiinaynaa in ardaygaaga {{student_name}} maanta uusan imaan dugsiga. Fadlan la soco xaalkiisa. — {{school_name}}','ATTENDANCE',1,1,'2026-09-17 11:47:03','2026-09-21 01:43:19'),(14,'RESULT_RELEASED','Exam Results Release Notice (Somali)','Natiijada Imtixaanka - {{student_name}}','Asc {{guardian_name}}, waxaan ku ogeysiinaynaa in natiijada {{student_name}} ee {{exam_name}} la sii daayay. Fadlan gal Student Portal si aad u aragto natiijada. — {{school_name}}','EXAMS',1,1,'2026-09-17 11:47:03','2026-09-17 12:40:56'),(15,'FEE_REMINDER','Tuition & Fee Balance Reminder (Somali)','Xasuusin Lacagta Dugsiga - {{student_name}}','Asc {{guardian_name}}, waxaan ku xasuusinaynaa in ardaygaaga {{student_name}} uu leeyahay lacag dugsi oo dhan {{fee_balance}} oo harsan. Fadlan gal Student Portal si aad u hubiso faahfaahinta. — {{school_name}}','FINANCE',1,1,'2026-09-17 11:47:03','2026-09-17 12:40:56'),(16,'GENERAL_ANNOUNCEMENT','General School Announcement (Somali)','Ogeysiis Muhiim ah - {{school_name}}','Asc {{guardian_name}}, waxaa jira ogeysiis cusub oo ka yimid {{school_name}}. Fadlan gal Student Portal si aad u akhrido faahfaahinta ogeysiiska.','GENERAL',1,1,'2026-09-17 11:47:03','2026-09-17 12:40:56');
