  `exam_name` varchar(100) NOT NULL,
  `class_id` int(11) NOT NULL,
  `academic_year` varchar(50) NOT NULL,
  `release_batch_id` int(11) DEFAULT NULL,
  `first_viewed_at` datetime NOT NULL,
  `last_viewed_at` datetime NOT NULL,
  `view_count` int(11) NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_student_exam_class_year_view` (`student_id`,`exam_name`,`class_id`,`academic_year`),
  KEY `ix_student_result_views_class_id` (`class_id`),
  KEY `ix_student_result_views_id` (`id`),
  KEY `ix_student_result_views_academic_year` (`academic_year`),
  KEY `ix_student_result_views_exam_name` (`exam_name`),
  KEY `ix_student_result_views_release_batch_id` (`release_batch_id`),
  KEY `ix_student_result_views_student_id` (`student_id`),
  CONSTRAINT `student_result_views_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_result_views_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_result_views_ibfk_3` FOREIGN KEY (`release_batch_id`) REFERENCES `result_release_batches` (`id`) ON DELETE SET NULL
